    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Personal Info state
    private string personalFullName = string.Empty;
    private string personalEmail = string.Empty;
    private string personalPhone = string.Empty;
    private string personalAddress = string.Empty;

    // Work History state
    private List<WorkHistoryStep.EntryModel> workEntries = new();

    // References state
    private List<ReferencesStep.ReferenceModel> references = new();

    // Cover Letter state
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

